// tilemap set up
scene.setBackgroundImage(assets.image`bookcase`)
tiles.setCurrentTilemap(assets.tile`tilemap`)

// sprite set up
let pictureFrame = sprites.create(assets.image`picture`)
tiles.placeOnTile(pictureFrame, tiles.getTileLocation(2, 1))

let crystalBall = sprites.create(assets.image`crystalBall`)
tiles.placeOnTile(crystalBall, tiles.getTileLocation(0, 0))

let hat = sprites.create(assets.image`hat`)
tiles.placeOnTile(hat, tiles.getTileLocation(0, 6))

let milkCarton = sprites.create(assets.image`milkCarton`)
tiles.placeOnTile(milkCarton, tiles.getTileLocation(0, 2))

